package ua.ember;
public final class ReactiveEngine {
 private double lastHit=-100;private int hits,previous=0xff5a1f,target=0xff5a1f;
 public void reset(){lastHit=-100;hits=0;previous=target=0xff5a1f;}
 public int render(String id,int basis,double now,EffectEngine.Signal audio,boolean hit){if(hit){lastHit=now;hits++;previous=target;target=hsv((hits%7)/7.0,1,1);}double age=now-lastHit,pulse=Math.exp(-age*5),strength=audio==null?0:Math.min(1,audio.rms*5),bass=audio==null?0:Math.min(1,audio.bass*7),light=0;int color=basis;
  switch(id){case "spark":color=EffectEngine.lerp(basis,0xffffff,Math.min(1,(audio==null?0:audio.peak)*2));light=Math.min(1,(audio==null?0:audio.peak)*2+pulse*.4);break;case "ocean":color=EffectEngine.lerp(0x001880,0x00dcff,bass);light=Math.min(1,strength*.4+bass);break;case "duo":color=hits%2==0?basis:hsv(hue(basis)+.5,1,1);light=Math.min(1,strength*.3+pulse);break;case "neon":color=hsv((hits%5)/5.0,.9,1);light=Math.min(1,bass*.5+pulse);break;case "pulse":light=.01+pulse*.99;break;case "bass":light=bass;break;case "jump3":color=new int[]{0xff0000,0x00ff00,0x0000ff}[hits%3];light=audio==null?0:.8;break;case "jump7":color=target;light=audio==null?0:.8;break;case "fade":color=EffectEngine.lerp(previous,target,age/.55);light=.01+Math.exp(-age*2.5)*.99;break;case "spectrum":if(audio!=null){int at=0;for(int i=1;i<32;i++)if(audio.spectrum[i]>audio.spectrum[at])at=i;color=hsv(at/32.0,1,1);}light=strength;break;case "wave":color=hsv(now*.045,1,1);light=strength;break;case "strobe":light=age<.13?1:0;break;case "fire":color=EffectEngine.lerp(0xc21e00,0xff9614,Math.min(1,bass+pulse*.5));light=Math.min(1,strength*.5+pulse);break;case "aurora":color=hsv(now*.025,.65,1);light=strength*(.55+.45*Math.sin(now*1.7));break;case "breath":light=strength*(.25+.75*(.5+.5*Math.sin(now*2)));break;case "echo":light=Math.max(pulse,age>.25?Math.exp(-(age-.25)*9)*.55:0);break;default:throw new IllegalArgumentException("Невідомий музичний ефект.");}
  return scale(color,Math.max(0,Math.min(1,light)));
 }
 private static double hue(int rgb){double r=((rgb>>16)&255)/255.0,g=((rgb>>8)&255)/255.0,b=(rgb&255)/255.0,max=Math.max(r,Math.max(g,b)),min=Math.min(r,Math.min(g,b)),d=max-min;if(d==0)return 0;double h=max==r?(g-b)/d:max==g?(b-r)/d+2:(r-g)/d+4;return(h/6+1)%1;}
 public static int scale(int rgb,double n){return ((int)Math.round(((rgb>>16)&255)*n))<<16|((int)Math.round(((rgb>>8)&255)*n))<<8|(int)Math.round((rgb&255)*n);}
 public static int hsv(double hue,double saturation,double value){double h=(hue%1+1)%1*6,c=value*saturation,x=c*(1-Math.abs(h%2-1)),m=value-c,r=0,g=0,b=0;switch((int)h){case 0:r=c;g=x;break;case 1:r=x;g=c;break;case 2:g=c;b=x;break;case 3:g=x;b=c;break;case 4:r=x;b=c;break;default:r=c;b=x;}return ((int)Math.round((r+m)*255))<<16|((int)Math.round((g+m)*255))<<8|(int)Math.round((b+m)*255);}
}
